mapper.sql:
WHERE deleted = 0
AND status = #{status}
AND (LOWER(company_name) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(taxpayer_id) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

mapper.update:
UPDATE invoice_title
SET subject_names = #{subjectName}
WHERE deleted = 0
  AND EXISTS (
      SELECT 1
      FROM invoice_title_subject relation_record
      WHERE relation_record.title_id = invoice_title.id
        AND relation_record.subject_id = #{subjectId}
  )
